export const DATA_08: ReadingTest[] = [
  { id: "rd-008", num: 8, title: "Đề 008", timeMin: 60, parts: [
    { title: "Popular Drinks in Vietnam", paragraphs: ["Vietnam is home to a rich and varied drink culture that reflects both local produce and decades of outside influence. From bustling city streets to quiet rural towns, people gather around drinks almost as often as they gather around food. Street vendors sell everything from strong black coffee to sweet fruit juices, sometimes within the very same block. This variety did not appear overnight, growing slowly as farmers, traders, and colonial rulers each left a mark on what ordinary Vietnamese people now drink every day.", "Coffee remains one of the most recognizable parts of Vietnamese drink culture, and much of its character comes from history rather than taste alone. French colonists introduced coffee cultivation in the nineteenth century, and Vietnam later became a leading producer of robusta beans, a variety known for its strong, slightly bitter flavor. Local drinkers eventually combined dark coffee with sweetened condensed milk, a substitute born from the scarcity of fresh milk at the time. The resulting beverage, often served over ice, is now considered a staple of everyday life rather than a luxury item.", "Iced tea, known locally as tra da, offers a different kind of story, one centered on hospitality rather than trade. In many restaurants and small shops, servers place a free glass of tea in front of guests before any order is taken. This gesture is not a marketing gimmick but a long-standing custom rooted in the idea that no guest should sit down thirsty. The tea itself is usually weak and mildly bitter, brewed from low-cost leaves rather than premium varieties, because its purpose is refreshment rather than flavor. They continue this practice even when profit margins are thin, treating it as a basic courtesy.", "On hot afternoons, many Vietnamese prefer something lighter than coffee or tea, and sugarcane juice, called nuoc mia, is a common choice. Vendors press stalks of sugarcane through a small machine, producing a pale green liquid that is served immediately over crushed ice. A similar drink, rau ma, is made from pennywort leaves and is valued less for its taste, which many newcomers find unusual, and more for its reputed cooling effect on the body during the hottest months. Both drinks are sold cheaply from small carts rather than formal shops, keeping them accessible to workers on tight budgets.", "In the evening, attention often turns to bia hoi, a fresh draft beer brewed daily and sold before it can lose its flavor. Unlike bottled beer, which can sit on shelves for months, bia hoi is meant to be consumed within a day or two of production, giving it a lighter and less consistent taste from batch to batch. Groups of friends and coworkers gather at small plastic tables along the sidewalk, turning the drink into a social ritual rather than a private habit. This tradition of shared, low-cost drinking has remained popular even as expensive imported beers have become available."], questions: [{ q: "According to the passage, why did Vietnamese drinkers begin adding condensed milk to coffee?", options: ["French colonists preferred condensed milk over black coffee.", "Condensed milk became popular after coffee prices increased sharply.", "Fresh milk was hard to obtain when the habit began.", "Robusta beans were too bitter without any added sugar."], answer: 2 }, { q: "The word \"staple\" in paragraph 2 is closest in meaning to _______.", options: ["basic necessity", "essential requirement", "popular flavor", "stable food"], answer: 0 }, { q: "What is the main idea of the passage?", options: ["Coffee production techniques changed significantly under French colonial rule.", "Social drinking customs matter more in Vietnam than the drinks' origins.", "Every drink in Vietnam originated as a direct response to poverty.", "Vietnam's diverse drinks combine local resources with historical outside influences."], answer: 3 }, { q: "According to the passage, which of the following is NOT mentioned as a reason people drink tra da?", options: ["It demonstrates hospitality toward all arriving guests.", "It has a reputed cooling effect on the body.", "It is offered before any order is actually placed.", "It is meant to provide refreshment and comfort."], answer: 1 }, { q: "According to the passage, how is nuoc mia typically served?", options: ["It is served warm to enhance its natural sweetness.", "It is prepared exclusively in formal restaurant kitchens.", "It is served right away with crushed ice.", "It is pressed from stalks using a manual or electric machine."], answer: 2 }, { q: "The word \"They\" in paragraph 3 refers to _______.", options: ["shop servers", "restaurants and small shops", "restaurant guests", "tea leaves"], answer: 1 }, { q: "The word \"ritual\" in paragraph 5 is closest in meaning to _______.", options: ["sacred ceremony", "cooking method", "ritzy event", "regular custom"], answer: 3 }, { q: "What can be inferred about bia hoi from the passage?", options: ["Its taste can vary because it is not stored for long.", "It is brewed daily so it always tastes identical to bottled beer.", "Its inconsistent taste is what causes it to spoil quickly.", "It is usually served in small plastic containers at sidewalk tables."], answer: 0 }, { q: "According to the passage, why do people value rau ma?", options: ["People value it mainly for its pleasant, sweet flavor.", "Tourists value it more than local residents do.", "People value it for its cooling effect in hot weather.", "It is made from pennywort leaves rather than sugarcane."], answer: 2 }, { q: "What is the author's main purpose in this passage?", options: ["To explain why French colonization changed Vietnamese coffee habits.", "To show how Vietnam's drinks reflect its history.", "To persuade readers to try Vietnamese street drinks personally.", "To criticize how commercialized Vietnam's beverage culture has become."], answer: 1 }] },
    { title: "The Rise of Tesla Electric Vehicles", paragraphs: ["Few companies have reshaped an industry's expectations as thoroughly as Tesla has reshaped the electric vehicle market. What began as a speculative venture, dismissed by many analysts as unlikely to survive its first decade, gradually forced established manufacturers to reconsider long-held assumptions. This did not happen simply because Tesla built a car that ran on batteries; others had tried that already. Its influence instead stemmed from a broader shift in how consumers came to view electric propulsion as a serious alternative.", "Tesla's origins trace back to 2003, when engineers founded the company to prove electric vehicles could outperform gasoline cars rather than merely match them. Elon Musk, who joined shortly afterward and later became chief executive, is most closely associated with the company today. Its first product, the Roadster, appeared in 2008 as a low-volume sports car built largely from components sourced elsewhere. Its performance, however, demonstrated something skeptics had doubted: an electric motor could accelerate rapidly without sacrificing everyday usability.", "While the Roadster proved a technical point, it was the Model S, launched in 2012, that signaled Tesla's intent to compete with luxury sedans rather than remain a niche curiosity. Sales figures alone do not fully explain its impact. Reviewers praised its handling, but the more lasting effect was psychological: it persuaded affluent buyers that an electric car need not involve any real trade-off in status. That shift in perception laid the groundwork for the mass-market Model 3, aimed at buyers who could not previously afford the brand.", "Underpinning these vehicles is a battery strategy few rivals have matched at comparable cost. Tesla invested early in large battery plants, known as gigafactories, betting that manufacturing at enormous volume would drive costs down faster than competitors who bought cells from outside suppliers. This carried real financial risk, since it meant committing billions before demand for electric vehicles was firmly established. The wager appears, according to several analysts, to have paid off, though rising lithium costs may narrow this advantage.", "A vehicle is only as useful as the infrastructure supporting it, and Tesla addressed this by building its own charging network rather than waiting for others. The Supercharger network, now spanning thousands of locations, let owners travel long distances without the range anxiety that had discouraged earlier buyers. Rival automakers often relied on networks run by unrelated companies, which frequently suffered from unreliable service and confusing payments. This gap in convenience may explain why Tesla kept a loyal customer base as rivals introduced comparable vehicles.", "By the middle of the 2020s, nearly every major automaker had launched its own electric lineup, a development some frame as validation of Tesla's vision and others as a genuine threat to its market position. Traditional manufacturers brought decades of production experience and dealer networks a company built from scratch could not easily replicate. Tesla responded by expanding production and lowering prices, even at the cost of narrower margins.", "None of this growth has come without difficulty. Production delays affected the Model 3 rollout for more than a year beyond projections, and the company's driver-assistance software, marketed as Autopilot, has faced sustained scrutiny following several high-profile accidents. Tesla maintains the technology reduces accident rates on average, though critics argue isolated incidents receive disproportionate attention because expectations were set unrealistically high. This tension between ambition and public trust remains an open question."], questions: [{ q: "According to the passage, what did the Roadster's performance demonstrate?", options: ["An electric motor could travel farther than any gasoline engine.", "An electric motor could accelerate quickly without losing daily practicality.", "Tesla's engineers proved batteries could be produced more cheaply than gasoline.", "The Roadster was built largely from components sourced from other manufacturers."], answer: 1 }, { q: "The word \"affluent\" in paragraph 3 is closest in meaning to _______.", options: ["moderately wealthy", "technically skilled", "financially wealthy", "influential public"], answer: 2 }, { q: "What is the main idea of the passage?", options: ["Tesla reshaped perceptions of electric vehicles well beyond its own sales figures.", "Tesla's Supercharger network solved the problem of charging anxiety.", "Tesla's battery specifications mattered more to buyers than its brand image.", "Every legacy automaker failed because it ignored electric vehicle technology entirely."], answer: 0 }, { q: "According to the passage, which of the following is NOT mentioned as a factor in Tesla's early growth?", options: ["Investment in every type of battery technology available", "Development of its own vehicle charging network", "A shift in buyer perception toward electric cars", "Government mandates requiring automakers to sell electric vehicles"], answer: 3 }, { q: "According to the passage, why was Tesla's gigafactory strategy financially risky?", options: ["It required abandoning partnerships with third-party battery suppliers entirely.", "It required massive spending before electric vehicle demand was proven.", "Government regulators demanded Tesla build factories in multiple countries.", "Rivals who purchased battery cells from third-party suppliers avoided this risk."], answer: 1 }, { q: "The phrase \"This gap\" in paragraph 5 refers to _______.", options: ["confusing payment systems used", "unrelated companies' reliability record", "the charging convenience difference", "marketing campaign spending overall"], answer: 2 }, { q: "The word \"disproportionate\" in paragraph 7 is closest in meaning to _______.", options: ["unfairly excessive", "slightly unequal", "financially costly", "proportional overall"], answer: 0 }, { q: "What can be inferred about Tesla's Autopilot software from the passage?", options: ["It reduces accidents on average, so no accidents have ever occurred.", "Public distrust of Autopilot caused the technology to become less safe.", "Production delays affected the Model 3 rollout by more than a year.", "Its overall safety record may be better than isolated incidents suggest."], answer: 3 }, { q: "According to the passage, how did the Model 3 relate to Tesla's later pricing strategy?", options: ["It was priced higher than the Model S to ensure exclusivity.", "It began a strategy of reaching buyers with lower prices over time.", "Legacy automakers introduced the Model 3 to compete with Tesla directly.", "The Model S signaled Tesla's intent to compete with luxury sedans."], answer: 1 }, { q: "What is the author's main purpose in this passage?", options: ["To detail the technical specifications of Tesla's battery gigafactories.", "To harshly condemn Tesla's handling of Autopilot safety concerns.", "To explain Tesla's broader impact on the electric vehicle industry.", "To celebrate Tesla's Supercharger network as the industry's best solution."], answer: 2 }] },
    { title: "Science and Technology During World War I", paragraphs: ["The First World War is often remembered for its human cost, yet its technological legacy arguably proved just as consequential, reshaping industries with little obvious connection to the battlefield. Unlike earlier wars, where technological change unfolded gradually across generations, the pressures of total war compressed decades of potential innovation into roughly four years. Governments diverted enormous resources toward research that, in peacetime, might never have been funded, and the resulting inventions did not simply improve existing weapons; several created entirely new categories of warfare.", "Among the most notorious developments was the large-scale use of chemical weapons, beginning with chlorine gas released by German forces in 1915 and later escalating to mustard gas, which caused injuries lingering long after exposure. What made these weapons disturbing was not merely their lethality but their psychological effect: soldiers accustomed to artillery now faced an enemy that could not be seen or predictably avoided. Armies raced to develop protective equipment, and early cloth masks gave way within a few years to more effective filtering respirators.", "Aircraft entered the war as fragile machines used mainly for aerial reconnaissance, allowing commanders to observe enemy positions rather than relying solely on ground scouts. Their role expanded once it became clear that denying an opponent's ability to observe was itself a tactical advantage. Pilots began carrying firearms, then machine guns synchronized to fire through spinning propellers, transforming aircraft into dedicated fighters, though its overall military impact remained modest compared to infantry and artillery.", "Battlefield communication posed a persistent challenge, since early radio equipment was bulky, unreliable, and vulnerable to interception. Commanders relied heavily on field telephones and, when wires were cut by shelling, on runners who carried messages on foot at considerable risk. Codebreaking emerged as an unexpected consequence of this reliance on transmitted messages: intercepted communications, once decrypted, occasionally provided advantages that influenced entire campaigns, a quieter aspect of wartime technology that some historians argue most directly shaped later intelligence gathering.", "Medical practice underwent equally significant transformation, driven by the scale of casualties requiring rapid treatment. Blood transfusion, previously experimental and risky, became more systematic once methods for storing blood were refined, saving lives otherwise lost to blood loss alone. Surgeons confronting disfiguring facial wounds developed early reconstructive techniques that later formed the foundation of modern plastic surgery, while triage systems, sorting the wounded by urgency, were retained by civilian hospitals long afterward.", "Ground warfare had settled into a stalemate of trenches and machine guns that made infantry advances devastatingly costly. Tanks were conceived specifically to break this deadlock , combining armor thick enough to resist small-arms fire with tracks capable of crossing the churned ground between trenches. Early models proved mechanically unreliable and slow, and their psychological effect on enemy soldiers, at least initially, outweighed their tactical one. Only toward the war's end did the vehicles fulfill the promise their inventors had imagined.", "None of these innovations, however, would have reached the front lines without a parallel transformation in industrial organization. Factories that had previously produced consumer goods were retooled for munitions, and standardized manufacturing allowed unprecedented quantities of material to be produced and shipped abroad. This mobilization left a lasting legacy: methods adopted out of wartime urgency persisted well into peacetime, quietly reshaping civilian industry long after the guns fell silent."], questions: [{ q: "According to the passage, what pattern connects the response to chemical weapons and the development of tanks?", options: ["Effective responses did not always arrive at the same pace across different technologies.", "Both defensive gas masks and early tanks proved effective almost immediately.", "Tanks appeared before chemical weapons and directly inspired protective mask designs.", "Mustard gas caused injuries that lingered long after exposure ended."], answer: 0 }, { q: "The word \"notorious\" in paragraph 2 is closest in meaning to _______.", options: ["mildly disliked", "recently discovered", "widely condemned", "noteworthy achievement"], answer: 2 }, { q: "According to the passage, why does codebreaking's significance receive special emphasis?", options: ["Frequent radio failures were caused by decrypted enemy intelligence.", "Some historians see it as more influential than any individual weapon.", "It was more reliable than radio, so it replaced radios entirely.", "Runners carried messages on foot when telephone wires were cut."], answer: 1 }, { q: "What is the main idea of the passage?", options: ["Chemical weapons forced armies to develop better protective equipment quickly.", "Industrial mobilization mattered more to the war's outcome than any single weapon technology.", "Every technology introduced during the war remained in permanent civilian use afterward.", "Wartime pressure compressed innovation across many unrelated fields at once."], answer: 3 }, { q: "According to the passage, which of the following is NOT mentioned as a wartime medical advance?", options: ["Vaccines against infectious disease were developed for the first time.", "Blood transfusion methods became more systematic and reliable.", "Triage systems sorted every wounded soldier by treatment urgency.", "Reconstructive surgery techniques later influenced modern plastic surgery."], answer: 0 }, { q: "The word \"its\" in paragraph 3 refers to _______.", options: ["aircraft", "aviation", "machine guns", "spinning propellers"], answer: 1 }, { q: "What can be inferred about the overall pace of wartime innovation from the passage?", options: ["All wartime technologies advanced at the same accelerated rate throughout the conflict.", "Slow tank development caused chemical weapons research to accelerate instead.", "Standardized manufacturing allowed large quantities of material to be produced.", "Acceleration occurred unevenly, with some innovations maturing far faster than others."], answer: 3 }, { q: "According to the passage, how does the industrial mobilization described relate to earlier-mentioned inventions like tanks and aircraft?", options: ["None of those inventions could have reached soldiers without matching industrial changes.", "Industrial mobilization began only after tanks proved militarily successful.", "Private companies, rather than governments, organized this industrial shift alone.", "Factories that once made consumer goods were retooled for munitions."], answer: 0 }, { q: "The word \"deadlock\" in paragraph 6 is closest in meaning to _______.", options: ["minor slowdown", "military alliance", "complete standstill", "locked door"], answer: 2 }, { q: "What is the author's main purpose in this passage?", options: ["To argue that chemical weapons were the war's most important innovation.", "To show how total war accelerated innovation across many different fields.", "To harshly condemn the militaries that developed these wartime technologies.", "To celebrate the medical advances made possible by wartime necessity."], answer: 1 }] },
    { title: "The Future of Artificial Intelligence in Vietnam", paragraphs: ["Not only has artificial intelligence become a fixture of global technology debates, but Vietnam itself has, somewhat more quietly, positioned itself as a nation determined to participate rather than merely observe. Whether this ambition will translate into genuine technological leadership, however, remains far from certain, complicated by infrastructure gaps that persist despite years of stated commitment. What distinguishes Vietnam's case from that of many developing economies is not the presence of ambition, which is common enough, but the speed with which policy rhetoric has been paired with concrete, if still uneven, investment.", "The government's national strategy, formally adopted in the early 2020s, set targets for AI research output and workforce development that many observers at the time considered optimistic, if not frankly unrealistic. [1] Subsequent progress has been mixed: research publication counts have risen substantially, [2] yet the translation of that research into commercially viable products has lagged behind targets in ways officials have been reluctant to acknowledge publicly. [3] Some analysts argue that the strategy's real achievement lies less in the targets themselves than in the institutional attention it generated, [4] attention that might not otherwise have been directed toward the sector.", "Universities have expanded computer science and data science programs considerably, though the quality of instruction varies widely between well-resourced institutions in major cities and smaller regional universities that struggle to recruit qualified faculty. This unevenness matters more than it might initially appear, since a workforce trained unevenly tends to concentrate expertise geographically, reinforcing rather than reducing regional disparities. Whether recent efforts to fund faculty exchanges will narrow this gap remains, at best, an open question that current data cannot yet answer with confidence.", "In practice, AI adoption has proceeded furthest in sectors where the return on investment is most immediately measurable, such as manufacturing quality control and financial fraud detection, rather than in sectors where benefits are diffuse or long-term. Agricultural applications, though frequently cited in official promotional material, have in fact been adopted more slowly, hindered by fragmented land ownership and limited access to sensors and connectivity such systems typically require. That gap between promotional emphasis and actual adoption rates suggests public narratives about AI's reach may be running ahead of the technology's practical footprint.", "Two structural obstacles appear, according to most available analyses, to constrain further progress more than any lack of ambition does. The first concerns data infrastructure: much of the data needed to train competitive AI systems remains fragmented across incompatible government and corporate databases, some of which are simply not digitized at all. The second concerns talent retention, since graduates trained in Vietnam's improving programs frequently accept offers from firms abroad, drawn by salaries and research opportunities domestic companies, for now, cannot match.", "Regulatory frameworks governing AI use have, perhaps unsurprisingly, developed more slowly than the technology itself, leaving questions of data privacy, algorithmic accountability, and labor displacement only partially addressed. Some officials maintain that premature regulation risks discouraging the very investment the country hopes to attract, while critics counter that delayed regulation risks normalizing practices that later prove difficult to reverse. Neither position has yet been tested by significant policy failure, which may explain why the debate remains largely theoretical.", "Taken together, these developments suggest neither the triumphant narrative favored by official communications nor the uniformly skeptical one offered by some critics, but something closer to a genuinely unresolved trajectory. Whether Vietnam's AI ambitions mature into durable technological capacity or instead settle into a permanent state of promising-but-incomplete development will likely depend less on any single policy decision than on how effectively the structural obstacles of data and talent are addressed over the coming decade."], questions: [{ q: "What is the main idea of the passage?", options: ["The author presents Vietnam's AI progress as genuinely uncertain rather than settled.", "The author confidently predicts Vietnam will become a leading AI power.", "The author is convinced Vietnam's AI ambitions will ultimately fail completely.", "The author focuses solely on evaluating the government's official AI strategy."], answer: 0 }, { q: "According to the passage, what does the gap between AI research output and commercial products suggest?", options: ["Officials have openly admitted that the research strategy completely failed.", "Rising research output directly caused commercial product development to slow down.", "Public claims of progress may not fully reflect commercial results.", "No research conducted under the strategy has ever become a commercial product."], answer: 2 }, { q: "The word \"diffuse\" in paragraph 4 is closest in meaning to _______.", options: ["highly concentrated", "spread out", "financially expensive", "confused thinking"], answer: 1 }, { q: "According to the passage, which of the following is NOT mentioned as an obstacle to Vietnam's AI development?", options: ["Much of the required data is fragmented across incompatible databases.", "Every university in Vietnam completely lacks qualified faculty.", "Skilled workers appear to find better opportunities outside the country.", "International sanctions have restricted Vietnam's access to AI hardware."], answer: 3 }, { q: "Which of the following square brackets [1] , [2] , [3] , or [4] best indicates where the following sentence could be added? 'Government officials, for their part, have continued to cite the strategy as evidence of steady progress.'", options: ["[1]", "[2]", "[3]", "[4]"], answer: 1 }, { q: "The phrase \"This unevenness\" in paragraph 3 refers to _______.", options: ["regional universities", "qualified faculty", "major cities", "quality variation"], answer: 3 }, { q: "According to the passage, how does the talent retention problem relate to the education system described earlier?", options: ["Better-trained graduates are the ones most likely to leave for opportunities abroad.", "Only graduates from smaller regional universities choose to work abroad.", "Talent retention problems caused universities to lower their admission standards.", "Domestic companies cannot match the salaries offered by firms abroad."], answer: 0 }, { q: "The word \"fragmented\" in paragraph 5 is closest in meaning to _______.", options: ["completely destroyed", "financially limited", "broken apart", "frequently updated"], answer: 2 }, { q: "What can be inferred about the debate over AI regulation described in the passage?", options: ["The debate will definitely end once new regulations are passed.", "The disagreement may stay unresolved until a real policy failure occurs.", "A recent policy failure has already forced regulators to intervene.", "Every country in the region faces this exact same regulatory debate."], answer: 1 }, { q: "What is the author's main purpose in this passage?", options: ["To strongly criticize the government's handling of AI policy.", "To praise universities for successfully closing regional education gaps.", "To explain why talent retention is Vietnam's only AI challenge.", "To present a balanced, unresolved picture of Vietnam's AI trajectory."], answer: 3 }] },
  ] },
  { id: "rd-117", num: 117, title: "Đề 117", timeMin: 60, parts: [
    { title: "The Rise of Extra Classes: Help or Hindrance?", paragraphs: ["In many countries around the world, attending extra classes outside of regular school hours has become a common part of student life. These classes — sometimes called tutoring sessions, supplementary classes, or cram schools — are designed to give students additional practice in subjects they find difficult or to help them prepare for important examinations. For millions of families, enrolling their children in extra classes feels like a natural and necessary investment in their future. However, educators and parents alike are beginning to ask whether this trend is genuinely helping students learn, or simply adding pressure to already busy young lives.", "The reasons why students attend extra classes vary considerably. Some students struggle with specific subjects such as mathematics or a foreign language and need individual attention that a crowded classroom cannot always provide. Others are preparing for high-stakes entrance examinations that determine admission to prestigious secondary schools or universities. In highly competitive education systems — particularly those found in South Korea, Japan, Vietnam, and Singapore — the pressure to perform well on these exams can be enormous, and extra classes are widely seen as an essential tool for gaining an advantage. They are often viewed not as a luxury but as a basic requirement for academic survival.", "Supporters of extra classes point to several clear benefits. First, smaller group sizes or one-on-one tutoring allow teachers to identify and address a student's specific weaknesses in a way that is rarely possible during regular school lessons. Second, the additional practice time helps students consolidate what they have already learned, reinforcing their understanding through repetition and varied exercises. Third, for students who are particularly motivated and academically ambitious, extra classes offer an opportunity to study material beyond the standard school curriculum, potentially preparing them for more advanced study in the future. Many students report feeling more confident after attending supplementary sessions, particularly before major examinations.", "Critics, however, raise a number of significant concerns. The most frequently cited problem is the impact on student wellbeing. Children and teenagers who attend school during the day and extra classes in the evening often have little time left for rest, play, or creative activities — all of which are considered essential for healthy development. Research in educational psychology has consistently shown that adequate sleep, physical activity, and unstructured leisure time contribute significantly to cognitive performance and emotional resilience. When extra classes encroach upon these essential activities, the short-term academic gains may come at a long-term developmental cost. A student who performs well in examinations but suffers from chronic fatigue and anxiety is not, by any meaningful measure, thriving.", "There is also the question of fairness. Extra classes are rarely free, and the cost of regular tutoring sessions can be substantial — placing them beyond the reach of families with limited financial resources. This creates a situation in which wealthier students have access to additional academic support that their less affluent peers simply cannot afford. Rather than leveling the playing field, the widespread reliance on extra classes may therefore deepen existing educational inequalities, rewarding students not for their natural ability or effort but for their family's capacity to pay. Some education researchers argue that this dynamic undermines the fundamental purpose of public education, which is to provide all students with an equal opportunity to succeed.", "Finding the right balance is not straightforward. Most educators agree that some degree of additional academic support is entirely reasonable, particularly for students who are genuinely struggling or preparing for significant examinations. The concern arises when extra classes become a default expectation rather than a targeted response to a specific need — when every student is assumed to require supplementary instruction simply to keep pace with their peers. In such an environment, the regular school day risks becoming a mere starting point, with the real education happening elsewhere, at additional cost and additional stress. Addressing this issue thoughtfully will require not only guidance for families but also a broader conversation about the values and priorities that education systems are designed to serve."], questions: [{ q: "What is the main idea of the passage?", options: ["Extra classes are an essential part of modern education and should be made available to all students regardless of their family income.", "Extra classes have become so widespread in competitive education systems that regular school instruction is no longer sufficient on its own.", "Extra classes offer certain academic advantages but also raise serious concerns about student wellbeing, fairness, and the purpose of education.", "The negative effects of extra classes on student health and family finances outweigh any academic benefits they may provide."], answer: 2 }, { q: "According to the passage, why are extra classes considered especially important in countries like South Korea, Vietnam, and Singapore?", options: ["Students in these countries are required by law to attend supplementary instruction before sitting for national examinations.", "High-pressure entrance examinations in these countries make additional preparation widely seen as necessary for academic success.", "School teachers in these countries are often underqualified and unable to deliver lessons that meet national curriculum standards.", "Extra classes in these countries are heavily subsidized by the government and therefore accessible to all families at low cost."], answer: 1 }, { q: "According to the passage, which of the following is stated as a benefit of extra classes for academically ambitious students?", options: ["They provide official certification that can be submitted alongside university entrance applications.", "They allow students to develop social skills through competitive group activities and peer discussion.", "They reduce the overall workload of regular schoolteachers by covering foundational content outside the classroom.", "They give students the opportunity to go beyond the standard school curriculum in preparation for more advanced study."], answer: 3 }, { q: "The word \"They\" in paragraph 2 refers to _______.", options: ["the prestigious secondary schools and universities that set demanding academic entry requirements", "extra classes, which are regarded as a fundamental necessity rather than an optional advantage", "the high-stakes entrance examinations that students in competitive education systems must prepare for", "the families who invest significant financial resources in their children's academic preparation"], answer: 1 }, { q: "According to the passage, what does research in educational psychology suggest about activities such as sleep and physical exercise?", options: ["They are beneficial primarily for younger children but become less important as students enter secondary school.", "They should be incorporated directly into the extra class schedule to offset the stress of additional academic work.", "They are recognized as important by educators but are difficult to prioritize within demanding school timetables.", "They contribute meaningfully to students' cognitive performance and their ability to manage emotional challenges."], answer: 3 }, { q: "According to the passage, how might the widespread use of extra classes affect educational equality?", options: ["It may prompt governments to increase public spending on education in order to reduce families' reliance on private tutoring.", "It may encourage schools to reduce the difficulty of their regular curriculum to accommodate students who cannot afford tutoring.", "It may give wealthier students a significant academic advantage that students from lower-income families are unable to access.", "It may gradually close the gap between high-performing and low-performing students by providing structured additional instruction."], answer: 2 }, { q: "According to the passage, which of the following is NOT mentioned as a benefit of extra classes?", options: ["Providing additional practice time that helps students reinforce and deepen their understanding of learned material.", "Allowing teachers to identify and address individual students' specific academic weaknesses more effectively.", "Improving students' social confidence by placing them in smaller peer groups with shared academic interests.", "Offering motivated students the chance to engage with content that goes beyond what is taught in regular school lessons."], answer: 2 }, { q: "The word \"encroach\" in paragraph 4 is closest in meaning to _______.", options: ["to replace an existing system with a more efficient and structured alternative approach", "to intrude upon or gradually take away time and space from something important", "to build gradually upon a foundation of previously established habits and daily routines", "to exceed the expected boundaries of a formal agreement or institutional arrangement"], answer: 1 }, { q: "The word \"consolidate\" in paragraph 3 is closest in meaning to _______.", options: ["to strengthen and deepen understanding by practicing and reviewing what has been learned", "to combine separate subjects into a single integrated course of instruction and assessment", "to formally record and document progress made during a structured period of study", "to divide a complex topic into smaller and more manageable units for easier learning"], answer: 0 }, { q: "What is the author's attitude toward extra classes as expressed throughout the passage?", options: ["Fully supportive, suggesting that extra classes are a necessary and beneficial response to the demands of competitive education.", "Primarily economic, focusing on the financial burden that extra classes place on families and the inequality this creates.", "Strongly critical, arguing that the harms of extra classes far outweigh any academic benefits they may offer students.", "Balanced and analytical, acknowledging that extra classes can be useful while also raising concerns about excess, inequality, and student wellbeing."], answer: 3 }] },
    { title: "Building Bridges Across Borders: ASEAN's Transnational Education Network", paragraphs: ["Over the past two decades, the Association of Southeast Asian Nations (ASEAN) has made the development of a regional education network one of its central policy priorities. What began as a relatively modest set of bilateral agreements between member states has gradually evolved into a more ambitious and institutionalized framework — one that seeks to harmonize academic qualifications, facilitate the movement of students and academics across national borders, and build a shared foundation of knowledge and skills suited to the demands of an increasingly interconnected regional economy. The emergence of this transnational education network reflects both the aspirations and the considerable challenges of regional integration in a bloc comprising ten nations with highly diverse histories, languages, economic conditions, and educational traditions.", "The cornerstone of ASEAN's educational cooperation is the ASEAN University Network (AUN), established in 1995 and currently comprising more than thirty member universities from across the region. AUN serves as the primary platform through which participating institutions collaborate on curriculum development, share research resources, and coordinate student exchange programs. One of AUN's most significant contributions has been the development of the AUN Quality Assurance framework, a set of standardized criteria designed to assess and improve the quality of degree programs at member universities. By establishing shared benchmarks for academic excellence, the framework aims to make qualifications granted at an Indonesian university, for instance, more legible and credible to employers and academic institutions in Thailand, Malaysia, or the Philippines. This mutual recognition of credentials is considered essential for creating a genuinely integrated regional labor market.", "Student mobility has emerged as one of the most visible expressions of ASEAN's educational integration agenda. Programs such as the ASEAN International Mobility for Students (AIMS) scheme enable undergraduates to spend one or two semesters studying at a partner university in another ASEAN country, with credits earned abroad recognized by their home institution. Participants in such programs frequently report gains that extend well beyond academic content: exposure to different teaching methodologies, immersion in an unfamiliar cultural environment, and the development of cross-cultural communication skills that are increasingly valued by regional employers. The experience of navigating daily life in a different language and social context is itself considered a form of education that cannot be replicated within the boundaries of a single national system. These benefits, however, are not uniformly distributed across participating countries, as institutions in wealthier member states tend to attract significantly more inbound exchange students than their counterparts in less economically developed nations.", "Beneath the institutional progress, significant structural obstacles continue to impede the full realization of ASEAN's educational ambitions. Language diversity presents one of the most persistent challenges: while English functions as ASEAN's working language and the medium of instruction at many participating universities, a substantial proportion of academic programs across the region are delivered in national languages, limiting accessibility for prospective exchange students. Differences in academic calendar structures — with some institutions operating on a semester system and others on a trimester or quarter schedule — create practical logistical difficulties for credit transfer arrangements. Perhaps most fundamentally, the wide variation in educational funding and infrastructure between wealthier members such as Singapore and Brunei and lower-income members such as Cambodia, Laos, and Myanmar means that the network risks entrenching existing inequalities rather than leveling them, with better-resourced institutions attracting the lion's share of collaboration opportunities and international visibility.", "Digital technology has emerged as a potentially transformative force in this context, offering pathways to educational cooperation that bypass some of the logistical constraints associated with physical mobility. ASEAN has invested in developing shared online learning platforms and open educational resources that allow students at institutions across the region to access high-quality course materials, regardless of whether their home university has the financial capacity to participate fully in exchange programs. Virtual joint seminars, collaborative online research projects, and shared digital libraries represent an expanding domain of transnational educational interaction that is less dependent on geographic proximity or institutional wealth. While online modalities cannot fully substitute for the transformative experience of studying abroad, they offer a more accessible and scalable alternative that may prove particularly valuable for students at institutions in less-connected parts of the region.", "Assessments of ASEAN's transnational education network tend to oscillate between optimism about its long-term potential and pragmatic concern about the slow pace of implementation. Critics point out that many of the network's most ambitious provisions — including the full mutual recognition of qualifications across all member states — remain aspirational rather than operational, hindered by the reluctance of individual governments to cede authority over credentialing to a supranational body. Supporters, meanwhile, argue that the network has already produced tangible benefits in the form of stronger inter-university partnerships, a growing cohort of regionally mobile graduates, and a shared institutional vocabulary for discussing educational quality. The ultimate test of ASEAN's educational vision will lie not in the sophistication of its policy documents but in whether its concrete achievements succeed in generating the human capital and mutual understanding that sustainable regional integration demands.", "For students across the region, the practical significance of these developments can vary enormously depending on the country and institution they attend. A student at a well-funded research university in Singapore or Malaysia may find herself with abundant opportunities for regional exchange, collaborative research, and international internships. Her counterpart studying at a small provincial university in Cambodia or Indonesia may have access to far fewer of these resources, despite nominally belonging to the same network. Closing this gap — not only through policy declarations but through sustained investment and capacity building — remains one of the most pressing challenges facing ASEAN's educational integration agenda as it enters its next phase of development."], questions: [{ q: "What is the main idea of the passage?", options: ["ASEAN's educational integration agenda has been largely unsuccessful due to persistent disagreements among member governments over qualification recognition.", "Digital technology has effectively resolved the logistical obstacles that previously prevented ASEAN member states from cooperating on higher education.", "ASEAN's transnational education network has successfully created a unified regional system of higher education that benefits all member states equally.", "ASEAN has developed a regional education network that has achieved significant progress in student mobility and quality assurance while continuing to face structural and equity-related challenges."], answer: 3 }, { q: "According to the passage, what is the primary purpose of the AUN Quality Assurance framework?", options: ["To create a unified ASEAN curriculum that all member universities are required to follow as a condition of network participation.", "To establish shared standards that make degree qualifications from one ASEAN country more recognizable and credible in other member states.", "To rank universities across ASEAN member states according to their research output and international academic reputation.", "To provide financial grants to underfunded universities so that they can improve their facilities and attract international exchange students."], answer: 1 }, { q: "The word \"These\" in paragraph 3 refers to _______.", options: ["the regional employers who increasingly value graduates with international study experience", "the ASEAN member countries that participate in the AIMS student mobility scheme", "the benefits gained through exchange programs, including cross-cultural skills, exposure to different teaching methods, and personal development", "the credit transfer arrangements that allow students to have qualifications earned abroad recognized by their home institution"], answer: 2 }, { q: "According to the passage, which of the following best describes the reported benefits of participating in student exchange programs under the AIMS scheme?", options: ["Students gain formal language certifications and professional internship experience that directly improve their employment prospects.", "Students receive financial scholarships and research fellowships that allow them to pursue graduate study at partner universities.", "Students develop academic knowledge, cross-cultural communication skills, and personal adaptability through immersion in a different environment.", "Students build professional networks with regional employers and government agencies through structured placement programs."], answer: 2 }, { q: "According to the passage, which of the following structural obstacles to ASEAN's educational integration is explicitly mentioned?", options: ["Differences in academic calendar structures create practical difficulties when students attempt to transfer credits between institutions.", "Political disagreements among member governments have repeatedly blocked the signing of bilateral academic cooperation agreements.", "The absence of a shared digital infrastructure makes it impossible for universities to exchange course materials electronically.", "A shortage of qualified English-language instructors in lower-income member states limits participation in joint degree programs."], answer: 0 }, { q: "According to the passage, which of the following is NOT mentioned as an obstacle to ASEAN's educational integration?", options: ["The use of different national languages as the medium of instruction across many academic programs in the region.", "Large disparities in educational funding and infrastructure between wealthier and lower-income member states.", "Inconsistent academic calendar systems that complicate the practical logistics of credit transfer arrangements.", "Reluctance among individual governments to allow a supranational body to oversee the recognition of academic qualifications."], answer: 3 }, { q: "According to the passage, why are digital tools considered particularly valuable for students at institutions in less-connected parts of the region?", options: ["Digital platforms allow these students to earn internationally recognized degrees without needing to relocate to a wealthier member country.", "Virtual programs are fully equivalent to the experience of studying abroad and can therefore replace physical exchange programs entirely.", "Digital resources enable universities in lower-income countries to receive direct funding transfers from better-resourced partner institutions.", "Online tools provide access to quality course materials and collaborative opportunities that are less dependent on institutional wealth or geographic location."], answer: 3 }, { q: "The word \"legible\" in paragraph 2 is closest in meaning to _______.", options: ["legally binding and formally enforceable under international academic accreditation agreements", "officially registered and recorded in a centralized ASEAN database of accredited higher education programs", "recognizable and understandable to institutions and employers outside the country where the qualification was awarded", "thoroughly evaluated and assigned a comparable numerical rating on a standardized international academic scale"], answer: 2 }, { q: "The word \"scalable\" in paragraph 5 is closest in meaning to _______.", options: ["designed to be evaluated and measured using standardized quantitative assessment tools and performance indicators", "capable of being expanded to reach a larger number of users without proportionally increasing cost or complexity", "dependent on a consistent and reliable technological infrastructure that must be maintained across all participating sites", "structured in a way that allows gradual customization based on the specific academic needs of individual institutions"], answer: 1 }, { q: "What can be inferred about the author's overall assessment of ASEAN's transnational education network?", options: ["The author argues that digital technology has already transformed ASEAN's educational cooperation to such a degree that traditional exchange programs are becoming obsolete.", "The author is largely optimistic, believing that the network's institutional frameworks are sufficiently robust to overcome its remaining challenges in the near future.", "The author takes a measured and critical stance, recognizing genuine achievements while emphasizing that persistent inequality and incomplete implementation continue to limit the network's impact.", "The author views the network as a well-intentioned but fundamentally flawed project whose structural inequities make meaningful regional integration unlikely."], answer: 2 }] },
    { title: "The Anatomy of Fake News: Origins, Spread, and Consequences", paragraphs: ["The term \"fake news\" has become one of the most contested phrases in contemporary public discourse, applied variously to deliberate political disinformation, commercially motivated fabrications, satirical content mistaken for fact, and legitimate journalism dismissed by those who find its conclusions inconvenient. This semantic instability is itself part of the problem: when the label is applied so promiscuously, it loses the analytical precision necessary to diagnose the specific mechanisms by which false or misleading information enters and distorts the public sphere. For the purposes of serious inquiry, fake news is most usefully defined as content that is intentionally fabricated or substantially misleading, presented in the format and register of legitimate journalism, and distributed with the aim of deceiving audiences for political, financial, or ideological gain. [1]", "The conditions that have made the contemporary fake news phenomenon so potent are not accidental. The structural transformation of the media landscape over the past two decades — driven principally by the rise of social media platforms, the collapse of traditional advertising revenue for established news organizations, and the fragmentation of audiences across algorithmically curated information environments — has created a set of incentive structures that systematically favor the production and circulation of emotionally provocative content over carefully verified reporting. On platforms such as Facebook, Twitter, and their successors, engagement metrics — likes, shares, and comments — function as the primary currency of visibility. Content that provokes strong emotional responses, particularly outrage, fear, or moral indignation, tends to be shared far more widely than content that is merely accurate and informative. Fabricated stories, freed from the constraints of factual verification, can be calibrated with precision to maximize this emotional impact, giving them a structural competitive advantage over responsible journalism in the attention economy.", "Research conducted by scholars at the Massachusetts Institute of Technology provides some of the most cited empirical data on this dynamic. A large-scale study published in the journal Science in 2018 analyzed the spread of approximately 126,000 news stories shared on Twitter over a period of roughly eleven years. The findings were striking: false stories reached audiences of one thousand or more users approximately six times faster than true stories, spread to significantly larger total audiences, and penetrated deeper into sharing networks. Crucially, the study found that human users — not automated bots — were primarily responsible for the accelerated diffusion of false content, a finding that complicates the common assumption that the fake news problem is essentially a technical one, solvable through algorithmic detection and bot removal. [2] The authors concluded that the novelty of false information — its tendency to be more surprising and emotionally resonant than accurate reporting — was the key variable explaining its superior virality.", "The consequences of widespread fake news extend well beyond the inconvenience of individual misinformation. At the political level, sustained exposure to disinformation has been linked to measurable erosion of public trust in democratic institutions, including electoral systems, judicial bodies, and mainstream media organizations. When citizens cannot reliably distinguish credible information from fabrication, the epistemic foundation upon which democratic deliberation depends — a broadly shared factual reality — is progressively undermined. Researchers studying the 2016 United States presidential election, the Brexit referendum in the United Kingdom, and several subsequent electoral contests in Europe and Latin America have documented the role of strategically deployed disinformation campaigns in shaping voter perceptions and, in some cases, measurably influencing electoral outcomes. The health domain offers equally alarming examples: during the COVID-19 pandemic, the World Health Organization coined the term \"infodemic\" to describe the simultaneous spread of accurate health guidance and dangerous misinformation, noting that the latter demonstrably contributed to vaccine hesitancy, delayed treatment-seeking behavior, and preventable mortality. [3]", "Efforts to counter fake news have proceeded along several parallel tracks. Fact-checking organizations — including PolitiFact, Full Fact, and Africa Check — have expanded their operations significantly, developing standardized methodologies for evaluating claims and publishing corrections accessible to the public. Social media platforms have, under sustained regulatory and public pressure, introduced labeling systems that attach warnings or context to posts identified as potentially misleading. Media literacy education has gained traction in school curricula across numerous countries, with programs designed to teach students to evaluate sources, identify logical fallacies, and recognize the visual and rhetorical conventions of fabricated content. Each of these approaches has demonstrated some measurable efficacy in controlled studies, yet each also faces significant limitations in scale, speed, and reach when compared with the velocity at which false content propagates through digital networks. [4]", "Perhaps the most sobering insight to emerge from the research literature is that corrections, even when accurate and timely, are frequently less effective than the original false claim at shaping lasting beliefs. Studies in cognitive psychology have documented a phenomenon known as the \"continued influence effect,\" whereby individuals continue to rely on information they have been explicitly told is false when making subsequent judgments, particularly when the false information provided a coherent causal explanation that the correction failed to replace. This asymmetry between the ease of introducing a false belief and the difficulty of dislodging it suggests that reactive strategies — debunking, labeling, correcting — are necessary but insufficient responses to the fake news challenge. Preventing the initial uptake of false information, through improved platform design, structural media reform, and sustained investment in public media literacy, may ultimately prove more consequential than any corrective intervention applied after the damage has already been done.", "The fake news problem is, at its core, an institutional and cultural challenge as much as a technological one. Solutions that focus exclusively on algorithmic detection or individual cognitive debiasing risk misdiagnosing the systemic conditions — economic, political, and social — that make the production and consumption of disinformation so persistently rewarding for those who generate it and so difficult to resist for those who encounter it. A durable response will require coordinated action across platforms, governments, educational systems, and civil society, sustained over a timescale that matches the depth of the problem rather than the urgency of any single news cycle."], questions: [{ q: "What is the central argument of the passage?", options: ["Social media platforms bear sole responsibility for the fake news crisis because their engagement-driven business models deliberately incentivize the production of emotionally provocative content.", "The most urgent priority in combating fake news is expanding the reach and funding of professional fact-checking organizations across all democratic societies.", "Fake news is primarily a technological problem that can be effectively resolved through improved algorithmic detection and the removal of automated bots from social media platforms.", "Fake news poses a profound and multidimensional challenge rooted in structural media conditions, human psychology, and institutional factors that no single intervention can adequately address."], answer: 3 }, { q: "According to the passage, why does fabricated content tend to achieve greater visibility than accurately reported journalism on social media platforms?", options: ["Social media algorithms are deliberately programmed by platform engineers to suppress credible journalism in favor of sensational or emotionally charged material.", "Fabricated content is produced at lower cost and higher volume by automated systems that can rapidly adapt to shifting audience preferences.", "Audiences on social media platforms are predominantly young and lack the media literacy skills required to distinguish fabricated stories from verified reporting.", "Fabricated content can be precisely engineered to provoke strong emotional reactions, which drive the engagement metrics that determine visibility on social platforms."], answer: 3 }, { q: "According to the passage, what did the MIT study's findings reveal about the primary drivers of false content diffusion on Twitter?", options: ["Stories containing visual media such as images and videos were found to spread more rapidly than text-based false content regardless of their factual accuracy.", "The rate at which false content spread was determined mainly by the political affiliation of the accounts that initially posted the fabricated stories.", "Automated bots were identified as the main agents responsible for accelerating the spread of false stories to large audiences.", "False stories spread faster and further than true stories primarily because of deliberate sharing decisions made by human users rather than automated systems."], answer: 3 }, { q: "The word \"calibrated\" in paragraph 2 is closest in meaning to _______.", options: ["structurally modeled on the conventions of established news formats in order to appear credible and authoritative", "precisely adjusted or fine-tuned with deliberate intent to achieve a specific and desired effect", "officially verified and approved by a recognized authority before being released to the general public", "randomly generated and distributed across multiple platforms to maximize the total number of users who encounter the content"], answer: 1 }, { q: "The word \"role\" in paragraph 4 refers to _______.", options: ["the responsibility that mainstream media organizations bear for failing to counter disinformation campaigns in real time during election periods", "the part played by international observers in documenting and reporting on disinformation strategies used in contested elections", "the institutional position occupied by electoral authorities in regulating the spread of political misinformation during official campaign periods", "the function or influence that strategically deployed disinformation campaigns have had in shaping voter perceptions and electoral outcomes"], answer: 3 }, { q: "According to the passage, which of the following counter-fake-news strategies is explicitly mentioned as having demonstrated measurable effectiveness in controlled studies?", options: ["Establishing independent government agencies with legal authority to issue fines against platforms that fail to remove disinformation within a set timeframe.", "Introducing mandatory registration systems for news websites so that fabricated outlets can be identified and removed from search engine results.", "Requiring social media companies to employ a minimum number of professional journalists to review trending content before it reaches large audiences.", "Developing media literacy curricula in schools designed to help students evaluate sources and recognize the conventions of fabricated content."], answer: 3 }, { q: "According to the passage, what does the \"continued influence effect\" suggest about strategies for combating fake news?", options: ["Individuals are highly receptive to accurate corrections provided that the correction is delivered within a short time of their initial exposure to false content.", "Corrections are most effective when delivered by trusted public figures rather than by anonymous fact-checkers or algorithmic labeling systems.", "The primary obstacle to effective debunking is the speed of social media sharing, which means corrections almost never reach the same audience as the original false claim.", "Even after being told that information is false, people often continue to use it in their reasoning, making reactive correction strategies insufficient on their own."], answer: 3 }, { q: "The word \"complicates\" in paragraph 3 is closest in meaning to _______.", options: ["significantly increases the administrative difficulty of implementing a proposed institutional policy change", "adds a layer of technical detail that makes an existing explanation harder for non-specialist audiences to follow", "challenges or undermines the validity of a widely held assumption by introducing contradictory evidence", "formally disproves and replaces a previously accepted scientific consensus with new empirical evidence"], answer: 2 }, { q: "According to the passage, which of the following is NOT mentioned as a strategy currently being used to counter the spread of fake news?", options: ["Legislative measures that impose criminal penalties on individuals who knowingly produce and distribute fabricated news content.", "Educational programs that teach students to assess the credibility of sources and identify the features of fabricated content.", "Fact-checking organizations that publish publicly accessible evaluations of potentially false claims using standardized methodologies.", "Social media platforms attaching warning labels or contextual information to posts identified as potentially misleading."], answer: 0 }, { q: "Which of the following square brackets [1] , [2] , [3] , or [4] best indicates where the following sentence could be added? 'This finding aligns with broader evidence suggesting that the emotional architecture of false content is deliberately engineered to override critical evaluation rather than to inform.'", options: ["[1]", "[2]", "[3]", "[4]"], answer: 1 }] },
    { title: "The Vocal Architecture of Avian Song: Attraction, Learning, and Evolution", paragraphs: ["Among the most extensively studied phenomena in behavioral biology, birdsong occupies a position of singular complexity. What appears to the casual listener as a pleasant, unstructured outpouring of sound is, upon closer examination, a tightly organized acoustic signal encoding information about the singer's species identity, geographic origin, individual identity, physiological condition, and reproductive fitness. The production of song for the purpose of mate attraction represents one of the most elaborate examples of sexual selection in the animal kingdom — a process in which certain traits evolve not because they enhance survival directly, but because they increase an individual's success in competing for reproductive partners. [1] Understanding the mechanisms and functions of avian song has accordingly become a central preoccupation of ornithologists, evolutionary biologists, neurobiologists, and cognitive scientists alike, each approaching the phenomenon from a distinct but complementary disciplinary vantage point.", "The physical apparatus responsible for birdsong — the syrinx — is anatomically distinct from the larynx that produces vocalization in mammals and represents one of evolution's more remarkable engineering solutions. Located at the base of the trachea, where it bifurcates into the two bronchi, the syrinx in many songbird species contains two independently controlled sets of vibrating membranes, allowing the bird to produce two separate sound streams simultaneously and blend them into complex harmonic structures that would be physically impossible for a single-membrane system to generate. This bilateral architecture is most highly developed in the oscines — the true songbirds, comprising approximately half of all bird species — and is considerably less elaborate in non-oscine groups. The neural control of the syrinx is mediated by a dedicated set of brain regions collectively known as the song control system, the discovery of which fundamentally altered neuroscientific understanding of how complex learned behaviors are represented and regulated in the vertebrate brain.", "From the perspective of mate attraction, the acoustic properties of a male's song serve as honest signals of his genetic quality and developmental history. The handicap principle, formalized by the evolutionary biologist Amotz Zahavi in the 1970s, provides one influential theoretical framework for understanding why costly signals — those that require significant physiological investment to produce — are reliable indicators of underlying quality: only genuinely fit individuals can afford to produce them without incurring prohibitive survival costs. Song complexity, measured in terms of repertoire size, the precision of note rendition, and the consistency of performance under varying environmental conditions, has been linked in numerous species to testosterone levels, body condition, parasite load, and the quality of early developmental nutrition. Female birds assessing potential mates therefore extract a wealth of physiological information from song characteristics that would be imperceptible to an untrained human observer. [2]", "The learning mechanisms through which juvenile birds acquire their species-typical songs have attracted particularly sustained scientific attention, partly because of the striking parallels they reveal between avian vocal learning and human language acquisition. Songbird learning proceeds through a series of broadly recognized phases. During an early \"sensitive period,\" the juvenile bird is exposed to the songs of adult conspecifics — typically the father or neighboring males — and forms an auditory template of the target song in memory without yet attempting to produce it. This phase is followed by a period of vocal practice, known as \"subsong\" or \"plastic song,\" during which the bird produces highly variable, exploratory vocalizations that bear only a rough resemblance to the memorized template. Through a process of sensorimotor learning — in which the bird continuously compares its own vocal output against the stored template and adjusts its production accordingly — the song gradually crystallizes into a stable, species-typical form. [3] In most temperate songbird species, this learning process is largely completed before the bird's first breeding season, though some species retain the capacity for song modification into adulthood.", "The geographic dimension of birdsong adds a further layer of complexity to this already intricate picture. Many songbird species exhibit regional dialects — systematic variations in song structure that distinguish populations separated by distance or geographic barriers — arising from the cultural transmission of locally learned vocal variants across successive generations. These dialects are not fixed by genetics; a young bird experimentally raised among adults singing a different dialect will typically acquire the dialect of its tutors rather than the one characteristic of its natal population. The existence of dialects raises intriguing questions about their functional significance: some researchers have proposed that dialect membership may serve as a local adaptation cue, enabling females to preferentially select mates whose song signals familiarity with local ecological conditions. Others have suggested that dialects function primarily as neutral byproducts of the geography of learning opportunities rather than as adaptively maintained signals in their own right. [4]", "The evolutionary pressures shaping song complexity are not, however, unidirectional. In species where males must also invest substantially in parental care, the trade-off between investing energy in elaborate song production and allocating resources to offspring provisioning may constrain the elaboration of song complexity in ways not predicted by simple sexual selection models. Furthermore, acoustic ecology — the relationship between the physical properties of a habitat and the transmission characteristics of sound — exerts considerable selective pressure on song structure. Species inhabiting dense forest environments tend to evolve songs dominated by pure, frequency-modulated tones that propagate efficiently through vegetation, while open-habitat species more frequently produce broader-bandwidth, rapidly modulated songs suited to the acoustic properties of grassland or aerial environments. The interaction between sexual selection, ecological constraint, and cultural transmission thus generates the extraordinary diversity of song forms observed across the roughly four thousand oscine species currently recognized by taxonomists.", "Recent advances in bioacoustics and machine learning have begun to transform the methodological landscape of birdsong research in ways that are accelerating discovery across all of the domains described above. Automated recording systems deployed across large geographic areas can now capture continuous acoustic data over entire breeding seasons, while neural network classifiers trained on spectrograms can identify species, individuals, and song variants with accuracy approaching that of expert human listeners. These tools are enabling researchers to address questions about song variation, mate choice, and dialect evolution at spatial and temporal scales that were previously inaccessible, and are simultaneously generating datasets of sufficient richness to test theoretical models that have long outpaced the empirical evidence available to evaluate them."], questions: [{ q: "Which of the following best summarizes the central focus of the passage?", options: ["Recent advances in machine learning and bioacoustics have fundamentally transformed our understanding of birdsong in ways that have rendered earlier theoretical frameworks obsolete.", "Birdsong is a multidimensional biological phenomenon whose complexity reflects the interaction of physical anatomy, learned behavior, sexual selection, ecological pressure, and cultural transmission.", "The primary significance of birdsong research lies in the parallels it reveals between avian vocal learning and human language acquisition rather than in its implications for evolutionary biology.", "Birdsong serves exclusively as a mechanism for species identification and territorial defense, with mate attraction representing only a secondary and relatively minor function."], answer: 1 }, { q: "According to the passage, what anatomical feature of the syrinx enables oscine songbirds to produce sounds of exceptional complexity?", options: ["Its location at the base of the trachea allows it to amplify resonance by drawing on the full length of the bird's respiratory column during vocalization.", "Its connection to a dedicated set of brain regions provides neural control precise enough to generate rapid alternations between fundamentally different sound types.", "Its possession of two independently controlled sets of vibrating membranes allows the simultaneous production and blending of two separate sound streams.", "Its bilateral architecture mirrors the structure of the human larynx and therefore produces overtone sequences that are acoustically similar to human speech patterns."], answer: 2 }, { q: "The word \"them\" in paragraph 2 refers to _______.", options: ["the two bronchi into which the trachea bifurcates at the location of the syrinx", "the neural signals transmitted from the song control system to the syrinx during vocalization", "the vibrating membranes contained within each side of the syrinx's bilateral structure", "the two separate sound streams produced simultaneously by the independently controlled membrane sets"], answer: 3 }, { q: "According to the passage, how does the handicap principle explain the reliability of birdsong as a signal of male quality?", options: ["It argues that costly signals are reliable indicators of quality because only genuinely fit individuals can sustain their production without incurring prohibitive survival costs.", "It proposes that only songs conforming to species-typical acoustic patterns are perceived as reliable by females, because deviations signal developmental abnormality.", "It demonstrates that females measure male quality by comparing song complexity against an internal benchmark derived from the songs of their own fathers.", "It suggests that males with larger song repertoires have survived longer and therefore accumulated greater experience of local ecological conditions and predator threats."], answer: 0 }, { q: "The word \"crystallizes\" in paragraph 4 is closest in meaning to _______.", options: ["stabilizes into a consistent, fixed form after a gradual process of comparison and adjustment during sensorimotor learning", "fragments into a series of distinct and independently memorized acoustic units that are later reassembled during performance", "transforms into a rigid template that the bird stores permanently in memory and reproduces without further modification", "becomes progressively more elaborate and varied as the bird incorporates new elements learned from multiple adult tutors"], answer: 0 }, { q: "According to the passage, what occurs during the \"subsong\" or \"plastic song\" phase of juvenile songbird development?", options: ["The juvenile bird produces highly variable and exploratory vocalizations that approximate but do not yet precisely replicate the memorized template.", "The juvenile bird broadcasts its developing song to attract responses from neighboring adults whose feedback guides further vocal refinement.", "The juvenile bird selectively imitates fragments of adult song that most closely match its own spontaneous vocalizations.", "The juvenile bird silently consolidates its auditory memory of the target song before attempting any form of vocal production."], answer: 0 }, { q: "According to the passage, what evidence suggests that regional dialects in birdsong are culturally rather than genetically transmitted?", options: ["Female birds raised in dialect boundary zones consistently prefer the songs of males whose dialect matches that of their own fathers.", "Dialect boundaries consistently align with geographic features such as rivers and mountain ranges that prevent gene flow between populations.", "Birds from different dialect regions produce acoustically identical songs when tested in laboratory conditions free from adult social influence.", "Young birds raised experimentally among adults singing a different dialect acquire that dialect rather than the one typical of their birth population."], answer: 3 }, { q: "The word \"constrain\" in paragraph 6 is closest in meaning to _______.", options: ["to redirect physiological resources away from one biological system toward another more immediately essential function", "to limit or restrict the degree to which a trait can develop due to competing demands or opposing selection pressures", "to eliminate a previously adaptive trait from a population once the environmental conditions that favored it have disappeared", "to fundamentally reverse the direction of an evolutionary trend by introducing an opposing selective pressure of greater magnitude"], answer: 1 }, { q: "According to the passage, which of the following is NOT mentioned as a physiological variable linked to song complexity in male songbirds?", options: ["The quality of nutritional resources available to the individual during its early developmental period.", "The individual's current parasite load and its impact on immune function and physical condition.", "The individual's testosterone levels and overall body condition at the time of song production.", "The individual's age and cumulative number of breeding seasons completed prior to the current year."], answer: 3 }, { q: "Which of the following square brackets [1] , [2] , [3] , or [4] best indicates where the following sentence could be added? 'This divergence of opinion underscores a broader methodological tension in evolutionary biology between adaptationist explanations and neutralist alternatives that has yet to be definitively resolved.'", options: ["[1]", "[2]", "[3]", "[4]"], answer: 3 }] },
  ] },
];
